import os
import re
import yaml
from six import string_types
from moler.util.moler_test import MolerTest  # type: ignore
from moler.config import read_yaml_configfile, reconfigure_logging_path  # type: ignore
from moler.config.loggers import get_logging_path  # type: ignore
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.tc.tc_params import merge_params
from taf.ul.sc.perf.testline.testline_loader import TestLineLoader
from taf.ul.sc.perf.util.helpers import get_library_path
from taf.ul.sc.perf.util.robot_helpers import get_builtin_value, set_suite_variable
from taf.ul.sc.perf.util.logger import (log_debug_function_info, log_function_info_to_console,
                                        log_function_status_to_console)


@log_function_info_to_console(msg="Load configuration")
@log_function_status_to_console(msg="Load test line configuration", log_hierarchy=2)
@log_debug_function_info()
def load_test_line_configuration():
    TestLineLoader()


@log_function_status_to_console(msg="Load run params", log_hierarchy=2)
@log_debug_function_info()
def load_run_params(tc_params=None, golden_params=None):
    if not tc_params:
        tc_params = get_builtin_value('TEST_RUN_PARAMS')
        if not tc_params:
            tc_params = load_tc_params()
    if not golden_params:
        golden_params = load_golden_params()

    tc.load_run_params(test_case_params=tc_params,
                       golden_params=golden_params)


def clear_params():
    tc.run_params.clear()
    tc.stats.clear()


def load_tc_params(tc_params_file=None):
    """
    For load few files you need to pass paths to files separated by :
    eg: -variable TC_PARAMS:/home/ute/common_pet_params.env:/home/ute/tc_params.ev

    :param tc_params_file: path to tc_params_file - if None get directly from robot
    :return: loaded params as dict
    """

    tc_params = {}
    if not tc_params_file:
        tc_params_file = get_builtin_value('TC_PARAMS')
        common_params_file = get_builtin_value('COMMON_PARAMS')
        if common_params_file:
            tc_params_file = "{}:{}".format(common_params_file, tc_params_file)

        if tc_params_file:
            tc_params_files = tc_params_file.split(":")
            for tc_file in tc_params_files:
                # TODO next file overwrite keys from previous file - need to change it
                _load_params(tc_params, tc_file)

    return tc_params


def load_golden_params():
    golden_params = {}
    load_procedure_params(golden_params)
    load_environment_params(golden_params)
    load_post_params(golden_params)

    return golden_params


def _load_params(golden_params=tc.run_params, params=None):
    if params:
        if isinstance(params, string_types):
            params = read_yaml_configfile(path=params)

        golden_params.update(params)


def _get_params_dir_path():
    return os.path.join(get_library_path(), 'params')


def load_procedure_params(golden_params=tc.run_params, procedure_params_file=None):
    golden_procedure_params_file = os.path.join(_get_params_dir_path(), 'procedure_params.env')
    if not procedure_params_file:
        procedure_params_file = get_builtin_value('PROCEDURE_PARAMS')

    merged_params = _merge_params_from_file(golden_procedure_params_file, procedure_params_file)
    _load_params(golden_params, merged_params)


def load_environment_params(golden_params=tc.run_params, env_params_file=None):
    golden_env_params_file = os.path.join(_get_params_dir_path(), 'environment_params.env')
    if not env_params_file:
        env_params_file = get_builtin_value('ENVIRONMENT_PARAMS')

    merged_params = _merge_params_from_file(golden_env_params_file, env_params_file)
    _load_params(golden_params, merged_params)


def load_post_params(golden_params=tc.run_params, post_params_file=None):
    golden_post_params_file = os.path.join(_get_params_dir_path(), 'post_params.env')
    if not post_params_file:
        post_params_file = get_builtin_value('POST_PARAMS')

    merged_params = _merge_params_from_file(golden_post_params_file, post_params_file)
    _load_params(golden_params, merged_params)


def _merge_params_from_file(file1, file2=None):
    params1 = read_yaml_configfile(path=file1)
    if file2:
        params2 = read_yaml_configfile(path=file2)
        merged_params = merge_params(params1, params2, clone_params=True)
    else:
        merged_params = params1

    return merged_params


def set_run_params_as_suite_variable():
    set_suite_variable('run_params', tc.run_params)


def print_test_run_parameters():
    MolerTest.info(msg="Test is running with parameters:", dump=tc.run_params)


def set_test_case_name():
    if 'test_case_name' not in tc.run_params or tc.run_params['test_case_name'] is None:
        test_name = get_builtin_value('TEST NAME')
        if test_name is None:
            test_name = _get_tc_name(get_builtin_value('TC_PARAMS'))
        if test_name is None:
            test_name = get_builtin_value('SUITE NAME')
        tc.run_params['test_case_name'] = test_name.replace(" ", "_")


def set_test_params_file():
    tc_params_file = get_builtin_value('TC_PARAMS')
    tc.run_params['environment']['test_params_file'] = tc_params_file


def set_test_case_dir():
    tc_params_file = tc.run_params['environment']['test_params_file']
    tc_params_files = tc_params_file.split(":")

    all_test_case_dirs = set()

    for tc_file in tc_params_files:
        all_test_case_dirs.add(os.path.dirname(os.path.abspath(tc_file)))

    reversed_test_case_dirs = list(all_test_case_dirs)[::-1]  # first dir has the highest priority in get_absolute_path

    suite_source = get_builtin_value('SUITE SOURCE')  # An absolute path to the suite file or directory
    if suite_source:
        suite_dir = os.path.dirname(suite_source) if os.path.isfile(suite_source) else suite_source
        reversed_test_case_dirs.append(os.path.abspath(suite_dir))

    tc.run_params['environment']['test_case_dir'] = reversed_test_case_dirs


def set_common_dir():
    common_dir = os.environ.get('COMMON_DIR', None)
    if common_dir:
        tc.run_params['environment']['common_dir'] = os.path.abspath(common_dir)


def set_test_line_dir():
    test_line_dir = os.environ.get('TEST_LINE_DIR', None)
    if test_line_dir:
        tc.run_params['environment']['test_line_dir'] = os.path.abspath(test_line_dir)


def set_robot_automatic_variables():
    set_test_case_name()
    set_test_params_file()
    if not tc.run_params['environment']['test_case_dir']:
        set_test_case_dir()
    set_test_line_dir()
    if not tc.run_params['environment']['common_dir']:
        set_common_dir()
    suite_name = get_builtin_value('SUITE NAME')
    tc.run_params['procedure_name'] = suite_name.replace(" ", "_")
    output_dir = get_builtin_value('OUTPUT DIR')
    tc.run_params['output_dir'] = output_dir
    tc.run_params['test_repository'] = get_test_repository_path()


def get_test_repository_path():
    test_repository = os.environ['TEST_REPOSITORY'] if 'TEST_REPOSITORY' in os.environ else None
    return test_repository


def _get_tc_name(tc_params_path):
    regex = re.compile(r"(.+)/(?P<DIRECTORY_NAME>[^/]+)/(?P<FILE_NAME>[^/]+)")
    match = regex.match(tc_params_path)

    return match.group('DIRECTORY_NAME')


def change_moler_log_dir(log_dir=None):
    if log_dir is None:
        log_dir = get_logging_path()
    reconfigure_logging_path(logging_path=log_dir)


def set_test_run_params(*args):
    """
    Keywords gives possibility set some parameters under robot test cases.
    Sample usage:

        Set Test Run Params
            ...   {
            ...  "duration": 300,
            ...  "scenario_name": "TM_high.scn"
            ...  }

    :param args:
    :return:
    """
    user_params = yaml.safe_load(''.join(args))
    set_suite_variable('TEST_RUN_PARAMS', user_params)
